function shortestStretch(nums: number[], k: number): number {
  let best = Infinity;
  for (let i = 0; i < nums.length; i++) {
    let sum = 0;
    for (let j = i; j < nums.length && j - i + 1 < best; j++) {
      sum += nums[j];
      if (sum >= k) { best = j - i + 1; break; }
    }
  }
  return best === Infinity ? -1 : best;
}

