function shortestStretch(nums: number[], k: number): number {
  const n = nums.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
  const dq = new Int32Array(n + 1);
  let head = 0, tail = 0, best = Infinity;
  for (let j = 0; j <= n; j++) {
    while (head < tail && P[j] - P[dq[head]] >= k) best = Math.min(best, j - dq[head++]);
    while (head < tail && P[dq[tail - 1]] >= P[j]) tail--;
    dq[tail++] = j;
  }
  return best === Infinity ? -1 : best;
}

